import{z as B,x as s,o as t,c as d,q as A,j as i,D as E,d as o,s as r,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"订单流的状态空间表示","description":"","frontmatter":{"title":"订单流的状态空间表示","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-flow-statespace.md","filePath":"quant/obd-flow-statespace.md","lastUpdated":1791413859000}'),p={name:"quant/obd-flow-statespace.md"};function m(F,a,u,c,f,h){const n=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=A('<h1 id="订单流的状态空间表示" tabindex="-1">订单流的状态空间表示 <a class="header-anchor" href="#订单流的状态空间表示" aria-label="Permalink to &quot;订单流的状态空间表示&quot;">​</a></h1><div class="epigraph"><p>签名成交量、订单流不平衡与队列失衡说着同一件事，又各自夹带噪声；状态空间不是多一个信号，是把「谁信几分」写成方程。</p><footer>—— 据 Cont, Kukanov and Stoikov, Journal of Financial Econometrics, 2014；Hasbrouck, Journal of Finance, 1995 整理</footer></div><p><a href="/quant/obd-impact-microfoundations">上一课</a>把冲击钉回簿的状态：同一笔订单流，簿密度不同，响应不同。要在线用起来——报价、执行、毒性检测——得回答「订单流现在处于什么状态」，而所有流量信号都是这个隐状态的带噪投影。本课把订单流写成状态空间：隐状态、观测通道、滤波器。它不是新信号，是把 <a href="/quant/ofi-toxicity">OFI</a>、签名成交、队列失衡、微价格的最优加权方式写成方程。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单一通道直接用都有病。签名成交量被拆单污染，母单碎片与反向单混在一起，符号序列短窗内几乎不可读。<a href="/quant/ofi-toxicity">OFI</a> 的原始设定只数最优档的增撤成，量在多档间转移时它会漏，跨档跳变更像方向反转。队列失衡看不到冰山，也读不出撤销背后的犹豫。三个通道覆盖的簿事件集不同、误差相关不高——这恰恰是融合的前提。缺口很具体：把多通道观测收成状态估计并给出不确定性；否则手工加权是在拟合回测，权重没有出处。</p><p><span class="marginnote">术语翻译：状态空间就是把「看不见的真实状态」与「看得见的带噪读数」分开写——状态按自己的规律演化，读数是状态的投影加噪声；滤波器干的活，是从一连串读数反推状态此刻最可能在哪、把握有多大。</span></p><h3 id="状态定义随任务而定" tabindex="-1">状态定义随任务而定 <a class="header-anchor" href="#状态定义随任务而定" aria-label="Permalink to &quot;状态定义随任务而定&quot;">​</a></h3><p>「订单流的状态」没有唯一答案，定义跟着下游任务走：执行关心短时净方向，做市关心条件毒性强度，研究关心流量的信息含量。同一套滤波机器，状态、观测矩阵与噪声假设不同；本课只管把状态估出来，状态怎么定价是下一课的事。</p><p><span class="marginnote">多档 OFI 是这个框架的第一个收益：把一档扩到前 \\(K\\) 档，在回归里是逐档重新拟合，在状态空间里只是给观测矩阵 \\(H\\) 加几行——「用几档」变成改一行配置，边际权重由滤波自动压低。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>线性高斯层：隐状态 \\(x_t\\) 按近似随机游走演化，观测 \\(y_t=Hx_t+\\varepsilon_t\\)，各通道的 \\(H\\) 行把 OFI、成交失衡、队列失衡、微价格偏离写成状态的投影。Kalman 滤波给出每步的估计与方差；噪声比稳定时，稳态增益可离线算成表——它就是各通道的最优权重，来源是信噪比，不是调参。经验基础是 <a href="/quant/ofi-toxicity">Cont, Kukanov and Stoikov</a> 的观测：中间价变动近似等于 \\(\\beta\\) 乘 OFI 加噪声，正是观测方程的形状。状态是离散体制（安静、知情、毒性）时换隐马尔可夫，分布重尾时用粒子滤波。滤波的副产品是创新——一步预测误差，「这笔流量比预期多出多少」的度量，下一课的动态逆向选择就吃它。</p>',11)),(t(),i(l,null,{default:E(()=>[r(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%9A%90%E7%8A%B6%E6%80%81%EF%BC%9A%E5%87%80%E6%96%B9%E5%90%91%2F%E6%AF%92%E6%80%A7%E5%BC%BA%E5%BA%A6%22%5D%20--%3E%20EV1%5B%22OFI%EF%BC%88%E5%A4%9A%E6%A1%A3%EF%BC%89%22%5D%0A%20%20X%20--%3E%20EV2%5B%22%E7%AD%BE%E5%90%8D%E6%88%90%E4%BA%A4%E5%A4%B1%E8%A1%A1%22%5D%0A%20%20X%20--%3E%20EV3%5B%22%E9%98%9F%E5%88%97%E5%A4%B1%E8%A1%A1%E4%B8%8E%E5%BE%AE%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20EV1%20--%3E%20KF%5B%22Kalman%2FHMM%20%E6%BB%A4%E6%B3%A2%22%5D%0A%20%20EV2%20--%3E%20KF%0A%20%20EV3%20--%3E%20KF%0A%20%20KF%20--%3E%20EST%5B%22%E7%8A%B6%E6%80%81%E4%BC%B0%E8%AE%A1%20%2B%20%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%80%A7%22%5D%0A%20%20EST%20--%3E%20INNO%5B%22%E5%88%9B%E6%96%B0%EF%BC%9A%E9%A2%84%E6%B5%8B%E8%AF%AF%E5%B7%AE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"融合优于单一通道的机制是误差的低相关：OFI 数簿事件，成交失衡数成交，队列失衡看存量，噪声来自不同的行为（拆单、冰山、犹豫性撤销），加权后按方差摊薄，信号按载荷叠加。滤波还给出不确定性。同样一串买单，估计方差大时少动，方差小时才值得重报价；省掉这个开关的系统，会在信号差的时段把噪声放大成动作。稳态增益还有制度解释：数据质量变差（丢包、口径改变）时观测噪声变大，增益应自动变钝；不随噪声重估增益的系统，等于假设数据和标定那天一样干净。",-1)),a[5]||(a[5]=e("p",null,"同一笔母单拆开的事件，在三个通道里留下的残影各不相同——融合为何更稳，可以沿着一个事件走一遍：",-1)),(t(),i(l,null,{default:E(()=>[r(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20MOM%5B%22%E6%AF%8D%E5%8D%95%E6%8B%86%E6%88%90%2050%20%E7%AC%94%E5%B0%8F%E4%B9%B0%E5%8D%95%E8%BF%9B%E5%9C%BA%22%5D%20--%3E%20C1%5B%22%E7%AD%BE%E5%90%8D%E6%88%90%E4%BA%A4%3A%E6%B7%B7%E5%85%A5%E5%8F%8D%E5%90%91%E5%8D%95%2C%E6%96%B9%E5%90%91%E8%A2%AB%E7%A8%80%E9%87%8A%22%5D%0A%20%20MOM%20--%3E%20C2%5B%22%E4%B8%80%E6%A1%A3%20OFI%3A%E4%BA%8C%E6%A1%A3%E6%8C%82%E6%8B%86%E7%9A%84%E9%83%A8%E5%88%86%E6%BC%8F%E6%A3%80%22%5D%0A%20%20MOM%20--%3E%20C3%5B%22%E9%98%9F%E5%88%97%E5%A4%B1%E8%A1%A1%3A%E4%B9%B0%E4%BE%A7%E5%AD%98%E9%87%8F%E5%A2%9E%2C%E5%86%B0%E5%B1%B1%E7%9C%8B%E4%B8%8D%E8%A7%81%22%5D%0A%20%20C1%20--%3E%20FUSE%5B%22%E6%BB%A4%E6%B3%A2%E6%8C%89%E4%BF%A1%E5%99%AA%E6%AF%94%E5%8A%A0%E6%9D%83%22%5D%0A%20%20C2%20--%3E%20FUSE%0A%20%20C3%20--%3E%20FUSE%0A%20%20FUSE%20--%3E%20OUT%5B%22%E5%87%80%E6%96%B9%E5%90%91%E4%BC%B0%E8%AE%A1%3A%E8%AF%AF%E5%B7%AE%E6%AF%94%E4%BB%BB%E4%B8%80%E5%8D%95%E9%80%9A%E9%81%93%E5%B0%8F%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">数字实例：三个通道噪声方差同为 1、误差互不相关时，等权平均后的噪声方差降到 1/3，标准差约 0.58——融合的收益就是这条方差摊薄。反过来，两通道误差高度相关时摊薄几乎失效，这正是「覆盖不同簿事件集」是融合前提的原因。</span></p><p>错误形态都很常见：直接吃签名成交量，系统对拆单过反应；只用一档 OFI，大单在二档挂拆时整个漏检；多信号线性相加却不讨论误差共线，权重由回归的偶然决定，换一只票就失效。</p><p><span class="marginnote">常见误区：初学者容易把滤波输出的「净方向」当成知情者的意图。它只是对近期订单流压力的最优猜测——不知道对手是谁，也保证不了下一笔还同向；把它拟人化地解读成「主力在吸筹」就超出了模型的承诺。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>状态空间是表示，不是因果：把估计出的「净方向」读成知情者的意图，超出了模型承诺。滤波有时滞——状态在动，估计落后半步，冲击响应快的时段这半步就是成本。观测字典依赖数据源：合并行情的聚合规则一变，\\(H\\) 整体搬家，增益要重估。最后，状态估计的验收和队列模型同一口径：不是似然最高，而是下游指标——执行滑点、报价盈亏——在使用估计后变好；验证怎么设计，本课程最后一单元再谈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>订单流的状态空间表示 = 隐状态 + 多通道观测 + 滤波，本质是把「谁信几分」写成增益。</li><li>单通道各有盲区：签名成交被拆单污染、一档 OFI 漏多档、队列失衡看不到冰山。</li><li>稳态 Kalman 增益是各通道的最优权重，来源是信噪比；噪声体制变了增益必须重估。</li><li>创新是流量的「意外」度量；状态定义随任务而定，验收在下游指标。</li><li>出处：Cont, Kukanov and Stoikov, <em>Journal of Financial Econometrics</em>, 2014；Hasbrouck, <em>Journal of Finance</em>, 1995；工程语境见 Cartea, Jaimungal and Penalva, <em>Algorithmic and High-Frequency Trading</em>, 2015。</li></ul>',7))])}const _=B(p,[["render",m]]);export{D as __pageData,_ as default};
